\set ON_ERROR_STOP on
SET client_encoding = 'UTF8';

-- P3 知识问答第一阶段：按文章分片建立普通索引检索。
-- 向量库可在数据量和语义召回要求提高后，作为独立存储逐步接入。
CREATE TABLE IF NOT EXISTS "kb_article_chunk" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "article_id" bigint NOT NULL,
  "space_id" bigint NOT NULL,
  "chunk_no" int NOT NULL,
  "content" text NOT NULL,
  "search_content" text NOT NULL,
  "char_start" int NOT NULL DEFAULT 0,
  "char_end" int NOT NULL DEFAULT 0,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE ("article_id", "chunk_no")
);
CREATE INDEX IF NOT EXISTS "kb_article_chunk_space_article" ON "kb_article_chunk" ("space_id", "article_id", "chunk_no");

INSERT INTO "kb_article_chunk" ("article_id", "space_id", "chunk_no", "content", "search_content", "char_start", "char_end")
SELECT a.id, a.space_id, 0, a.content, a.search_content, 0, LENGTH(a.search_content)
FROM "kb_article" a
WHERE a.deleted = 0
  AND NOT EXISTS (SELECT 1 FROM "kb_article_chunk" c WHERE c.article_id = a.id);

